function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 1000) return 'nums needs 2 to 1000 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= -1000000000 && v <= 1000000000)) return 'Each value is an integer from -10^9 to 10^9.';
  return null;
}

