function findSubarrays(nums) {
  const seen = new Set();
  for (let i = 0; i + 1 < nums.length; i++) {
    const sum = nums[i] + nums[i + 1];
    if (seen.has(sum)) {
      return true;
    }
    seen.add(sum);
  }
  return false;
}

