function findSubarrays(nums) {
  const n = nums.length;
  for (let a = 0; a + 1 < n; a++)
    for (let b = a + 1; b + 1 < n; b++)
      if (nums[a] + nums[a + 1] === nums[b] + nums[b + 1]) return true;
  return false;
}

