function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const LIMIT = 1000000000;
  const small = size === 'small';
  const n = small ? int(2, 8) : int(900, 1000);
  const mode = int(0, 3);
  let nums;
  if (mode === 0) {
    // Values from a narrow range: repeated sums are likely.
    const span = small ? int(1, 4) : int(5, 400);
    nums = Array.from({ length: n }, () => int(-span, span));
  } else if (mode === 1) {
    // Values from the full range: repeated sums are very unlikely.
    nums = Array.from({ length: n }, () => int(-LIMIT, LIMIT));
  } else if (mode === 2) {
    // Strictly increasing values give strictly increasing sums, so no sum repeats.
    let value = int(-LIMIT, -LIMIT + 1000);
    nums = [];
    for (let k = 0; k < n; k++) { nums.push(value); value += int(1, small ? 5 : 1000000); }
  } else {
    // Increasing values, then one window copied elsewhere so exactly one sum repeats.
    let value = int(-1000, 1000);
    nums = [];
    for (let k = 0; k < n; k++) { nums.push(value); value += int(1, 10); }
    if (n >= 3) {
      const from = int(0, n - 2);
      let to = int(0, n - 2);
      if (to === from) to = from === 0 ? 1 : from - 1;
      nums[to] = nums[from];
      nums[to + 1] = nums[from + 1];
    }
  }
  return [nums];
}
